/** Pick the phase from the user prompt ("NOW WRITE PHASE 3: …"). */
export function mselResponder(req: ChatRequest): MselPhaseOutput {
  const user = req.messages.find((m) => m.role === 'user')?.content ?? ''
  const n = Number(/NOW WRITE PHASE (\d+)/.exec(user)?.[1] ?? 1)
  return MSEL_PHASES[Math.min(MSEL_PHASES.length, Math.max(1, n)) - 1]!
}

